<?php namespace App\Http\Controllers; use App\Models\{Product,StockTransaction}; use Illuminate\Http\Request; class ReportController extends Controller {public function __invoke(Request $r,string $type='inventory'){$rows=$type==='inventory'?Product::with(['supplier','warehouse'])->get():StockTransaction::with(['supplier','salesperson','items.product'])->where('type',$type==='inbound'?'in':'out')->latest('transaction_date')->get();return view('reports.index',compact('rows','type'));}}
